514→                  ? { ...m, currentPhase: 'answer', segments: [...state.segments] }
515→                  : m
516→              )
517→            );
518→          },
519→          onToolCall: (pending: ToolCallResult) => {
520→            flushNow();
521→            if (state.currentText.trim()) {
522→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
523→              state.segments.push({ type: segType, text: state.currentText });
524→              state.currentText = '';
525→            }
526→            state.segments.push({ type: 'tool', toolResult: pending });
527→            updateMessages(msgs =>
528→              msgs.map(m =>
529→                m.id === assistantId
530→                  ? { ...m, currentPhase: 'answer', segments: [...state.segments] }
531→                  : m
532→              )
533→            );
534→          },
535→          onToolResult: (result: ToolCallResult) => {
536→            const pendingIdx = state.segments.findIndex(
537→              s => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
538→            );
539→            if (pendingIdx !== -1) {
540→              const pending = state.segments[pendingIdx].toolResult!;
541→              state.segments[pendingIdx] = {
542→                type: 'tool',
543→                toolResult: {
544→                  ...pending,
545→                  ...result,
546→                  sql: result.sql || pending.sql,
547→                  toolName: result.toolName || pending.toolName,
548→                  command: result.command || pending.command,
549→                  toolInput: result.toolInput || pending.toolInput,
550→                },
551→              };
552→            } else {
553→              state.segments.push({ type: 'tool', toolResult: result });
554→            }
555→            updateMessages(msgs =>
556→              msgs.map(m =>
557→                m.id === assistantId
558→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...state.segments] }
559→                  : m
560→              )
561→            );
562→            refreshTables();
563→          },
564→          onSubagentStart: (data) => {
565→            flushNow();
566→            if (state.currentText.trim()) {
567→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
568→              state.segments.push({ type: segType, text: state.currentText });
569→              state.currentText = '';
570→            }
571→            state.segments.push({
572→              type: 'subagent_start',
573→              subagentId: data.id,
574→              subagentName: data.name,
575→              text: data.prompt,
576→            });
577→            updateMessages(msgs =>
578→              msgs.map(m =>
579→                m.id === assistantId
580→                  ? { ...m, segments: [...state.segments] }
581→                  : m
582→              )
583→            );
584→          },
585→          onSubagentEnd: (data) => {
586→            state.segments.push({
587→              type: 'subagent_end',
588→              subagentId: data.id,
589→              subagentName: data.name,
590→              chart_spec: data.chart_spec,
591→              sqlResults: data.sql_results,
592→              text: data.result,
593→            });
594→            updateMessages(msgs =>
595→              msgs.map(m =>
596→                m.id === assistantId
597→                  ? { ...m, segments: [...state.segments] }
598→                  : m
599→              )
600→            );
601→          },
602→          onDone: (newSessionId) => {
603→            if (newSessionId) {
604→              state.sessionId = newSessionId;
605→              sessionIdRef.current = newSessionId;
606→            }
607→            flushNow();
608→            if (state.currentText.trim()) {
609→              state.segments.push({ type: 'answer', text: state.currentText });
610→              state.currentText = '';
611→            }
612→            updateMessages(msgs =>
613→              msgs.map(m =>
614→                m.id === assistantId
615→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...state.segments] }
616→                  : m
617→              )
618→            );
619→            cleanupStream();
620→            if (activeConversationIdRef.current === convId) {
621→              setIsStreaming(false);
622→            } else if (convId) {
623→              messagesCacheRef.current.set(convId, state.messages);
624→            }
625→          },
626→          onError: (error) => {
627→            flushNow();
628→            if (state.currentText.trim()) {
629→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
630→              state.segments.push({ type: segType, text: state.currentText });
631→              state.currentText = '';
632→            }
633→            state.segments.push({ type: 'error', errorMessage: error });
634→            updateMessages(msgs =>
635→              msgs.map(m =>
636→                m.id === assistantId
637→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...state.segments] }
638→                  : m
639→              )
640→            );
641→            cleanupStream();
642→            if (activeConversationIdRef.current === convId) {
643→              setIsStreaming(false);
644→            } else if (convId) {
645→              messagesCacheRef.current.set(convId, state.messages);
646→            }
647→          },
648→          onUserQuestion: (data) => {
649→            flushNow();
650→            if (state.currentText.trim()) {
651→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
652→              state.segments.push({ type: segType, text: state.currentText });
653→              state.currentText = '';
654→            }
655→            state.segments.push({ type: 'user_question', questionData: data });
656→            updateMessages(msgs =>
657→              msgs.map(m =>
658→                m.id === assistantId
659→                  ? { ...m, segments: [...state.segments] }
660→                  : m
661→              )
662→            );
663→          },
664→        },
665→        controller.signal,
666→        userSessionId,
667→        convId,
668→      );
669→    },
670→    [flushTextForStream, refreshTables, userSessionId]
671→  );
672→
673→  const deleteMessage = useCallback(
674→    (messageIndex: number) => {
675→      const convId = activeConversationIdRef.current;
676→      // Only block if this specific conversation is streaming
677→      if (convId && streamStatesRef.current.has(convId)) return;
678→
679→      // Store remaining messages as history for Langfuse context on next send
680→      setMessages((prev) => {
681→        const remaining = prev.slice(0, messageIndex);
682→        pendingHistoryRef.current = remaining
683→          .filter((m) => m.role === 'user' || m.role === 'assistant')
684→          .map((m) => ({ role: m.role, content: m.content }));
685→        return remaining;
686→      });
687→
688→      // Persist the truncation to the backend
689→      if (convId) {
690→        fetch(`/api/conversations/${convId}/messages?from_sort_order=${messageIndex}`, {
691→          method: 'DELETE',
692→        }).catch(() => {
693→          // Best-effort: if this fails the UI is already updated
694→        });
695→        // Invalidate cache so switching back loads from backend
696→        messagesCacheRef.current.delete(convId);
697→      }
698→
699→      // Clear session so next message starts fresh
700→      sessionIdRef.current = null;
701→    },
702→    []
703→  );
704→
705→  const respondToQuestion = useCallback(
706→    async (questionId: string, answers: string[], freeText?: string) => {
707→      // Find the stream state that contains this question
708→      let targetState: StreamState | undefined;
709→      let targetConvId: string | null = null;
710→
711→      // Search all active streams for the question
712→      for (const [cid, state] of streamStatesRef.current) {
713→        if (state.segments.some(s => s.type === 'user_question' && s.questionData?.questionId === questionId)) {
714→          targetState = state;
715→          targetConvId = cid;
716→          break;
717→        }
718→      }
719→
720→      if (targetState) {
721→        const segIdx = targetState.segments.findIndex(
722→          s => s.type === 'user_question' && s.questionData?.questionId === questionId
723→        );
724→        if (segIdx !== -1) {
725→          targetState.segments[segIdx] = {
726→            ...targetState.segments[segIdx],
727→            userAnswer: answers,
728→            userFreeText: freeText,
729→          };
730→          targetState.messages = targetState.messages.map(m =>
731→            m.id === targetState!.assistantId
732→              ? { ...m, segments: [...targetState!.segments] }
733→              : m
734→          );
735→          if (activeConversationIdRef.current === targetConvId) {
736→            setMessages(targetState.messages);
737→          }
738→        }
739→      }
740→
741→      // POST to backend
742→      try {
743→        await fetch('/api/chat/respond', {
744→          method: 'POST',
745→          headers: {
746→            'Content-Type': 'application/json',
747→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
748→          },
749→          body: JSON.stringify({
750→            question_id: questionId,
751→            answers,
752→            free_text: freeText || null,
753→          }),
754→        });
755→      } catch (e) {
756→        console.error('Failed to respond to question:', e);
757→      }
758→    },
759→    [userSessionId]
760→  );
761→
762→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
763→    const outgoing = outgoingConversationId || null;
764→    const incoming = incomingConversationId || null;
765→    activeConversationIdRef.current = incoming;
766→
767→    // Save outgoing conversation's messages to cache (only if not streaming --
768→    // streaming conversations keep their state in streamStatesRef)
769→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
770→      const currentMsgs = messagesRef.current;
771→      if (currentMsgs.length > 0) {
772→        messagesCacheRef.current.set(outgoing, currentMsgs);
773→      }
774→    }
775→
776→    // Check if incoming conversation has an active stream (re-attachment)
777→    if (incoming) {
778→      const streamState = streamStatesRef.current.get(incoming);
779→      if (streamState) {
780→        // Re-attach: use live stream messages
781→        setMessages(streamState.messages);
782→        setIsStreaming(true);
783→        return;
784→      }
785→    }
786→
787→    // No active stream -- use backend data or cache
788→    let finalMsgs = msgs;
789→    if (incoming) {
790→      const cached = messagesCacheRef.current.get(incoming);
791→      if (cached && cached.length > 0 && cached.length > msgs.length) {
792→        finalMsgs = cached;
793→      }
794→      messagesCacheRef.current.delete(incoming);
795→    }
796→
797→    setMessages(finalMsgs);
798→    const hasStreamingMsg = finalMsgs.some(m => m.isStreaming);
799→    setIsStreaming(hasStreamingMsg);
800→    sessionIdRef.current = null;
801→    pendingHistoryRef.current = null;
802→  }, []);
803→
804→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
805→    const outgoing = outgoingConversationId || null;
806→    activeConversationIdRef.current = null;
807→
808→    // Save outgoing messages to cache if not streaming
809→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
810→      const currentMsgs = messagesRef.current;
811→      if (currentMsgs.length > 0) {
812→        messagesCacheRef.current.set(outgoing, currentMsgs);
813→      }
814→    }
815→
816→    setMessages([]);
817→    setIsStreaming(false);
818→    sessionIdRef.current = null;
819→    pendingHistoryRef.current = null;
820→  }, []);
821→
822→  return (
823→    <AgentContext.Provider
824→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion, streamingConversationIds }}
825→    >
826→      {children}
827→    </AgentContext.Provider>
828→  );
829→}
