  8→import { AgentContext } from '../hooks/useAgent';
  9→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
 10→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 11→import { useSessionId } from '../hooks/useSessionId';
 12→import { generateUUID } from '../utils/uuid';
 13→
 14→interface StreamState {
 15→  assistantId: string;
 16→  segments: ContentSegment[];
 17→  currentText: string;
 18→  textBuffer: string;
 19→  phase: 'thinking' | 'answer';
 20→  abortController: AbortController;
 21→  sessionId: string | null;
 22→  messages: ChatMessage[];
 23→  flushTimer: ReturnType<typeof setTimeout> | null;
 24→}
 25→
 26→function generateId() {
 27→  return generateUUID();
 28→}
 29→
 30→export function AgentProvider({
 31→  children,
 32→  refreshTables,
 33→}: {
 34→  children: ReactNode;
 35→  refreshTables: () => Promise<void>;
 36→}) {
 37→  const userSessionId = useSessionId();
 38→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 39→  const [isStreaming, setIsStreaming] = useState(false);
 40→  const sessionIdRef = useRef<string | null>(null);
 41→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 42→  // Keep a ref in sync with messages so sendMessage always reads the latest
 43→  const messagesRef = useRef<ChatMessage[]>(messages);
 44→  useEffect(() => { messagesRef.current = messages; }, [messages]);
 45→  // Cache messages per conversation so switching away doesn't lose in-progress data
 46→  const messagesCacheRef = useRef<Map<string, ChatMessage[]>>(new Map());
 47→  // Track which conversation is currently displayed so background streams can detect they're stale
 48→  const activeConversationIdRef = useRef<string | null>(null);
 49→
 50→  // Per-conversation stream state map (replaces all singleton streaming refs)
 51→  const streamStatesRef = useRef<Map<string, StreamState>>(new Map());
 52→  const [streamingConversationIds, setStreamingConversationIds] = useState<Set<string>>(new Set());
 53→
 54→  const flushTextForStream = useCallback((state: StreamState, conversationId: string) => {
 55→    const text = state.textBuffer;
 56→    if (!text) return;
 57→    state.currentText += text;
 58→    state.textBuffer = '';
 59→
 60→    // Update the stream's own messages
 61→    state.messages = state.messages.map((m) =>
 62→      m.id === state.assistantId ? { ...m, content: m.content + text } : m
 63→    );
 64→
 65→    // If this conversation is currently being viewed, update React state
 66→    if (activeConversationIdRef.current === conversationId) {
 67→      setMessages(state.messages);
 68→    }
 69→  }, []);
 70→
 71→  const sendMessage = useCallback(
 72→    async (text: string, conversationId?: string | null) => {
 73→      const convId = conversationId || null;
 74→      // Per-conversation guard: don't double-send in same conversation
 75→      if (convId && streamStatesRef.current.has(convId)) return;
 76→
 77→      const controller = new AbortController();
 78→      const assistantId = generateId();
 79→
 80→      const userMsg: ChatMessage = {
 81→        id: generateId(),
 82→        role: 'user',
 83→        content: text,
 84→      };
 85→      const assistantMsg: ChatMessage = {
 86→        id: assistantId,
 87→        role: 'assistant',
 88→        content: '',
 89→        toolCalls: [],
 90→        isStreaming: true,
 91→      };
 92→
 93→      // Build conversation history from current messages or cached messages
 94→      const currentMsgs = convId && activeConversationIdRef.current === convId
 95→        ? messagesRef.current
 96→        : (convId ? messagesCacheRef.current.get(convId) : messagesRef.current) || messagesRef.current;
 97→      const history = currentMsgs
 98→        .filter((m) => m.role === 'user' || m.role === 'assistant')
 99→        .map((m) => ({ role: m.role, content: m.content }));
100→
101→      const streamMessages = [...currentMsgs, userMsg, assistantMsg];
102→
103→      // Create per-conversation stream state
104→      const state: StreamState = {
105→        assistantId,
106→        segments: [],
107→        currentText: '',
108→        textBuffer: '',
109→        phase: 'thinking',
110→        abortController: controller,
111→        sessionId: sessionIdRef.current,
112→        messages: streamMessages,
113→        flushTimer: null,
114→      };
115→
116→      if (convId) {
117→        streamStatesRef.current.set(convId, state);
118→        setStreamingConversationIds(prev => new Set(prev).add(convId));
119→      }
120→
121→      // If this is the active conversation, update React state
122→      if (activeConversationIdRef.current === convId) {
123→        setMessages(streamMessages);
124→        setIsStreaming(true);
125→      }
126→
127→      // If there's pending history from a delete, start a new Langfuse session
128→      const pendingHistory = pendingHistoryRef.current;
129→      pendingHistoryRef.current = null;
130→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
131→
132→      // Extract skill references
133→      let actualMessage = text;
134→      let skills: string[] | undefined;
135→      const slashMatches = [...text.matchAll(/\/([a-z0-9-]+)/g)];
136→      if (slashMatches.length > 0) {
137→        skills = slashMatches.map((m) => m[1]);
138→        actualMessage = slashMatches.reduce((msg, m) => msg.replace(m[0], ''), text).trim() || text;
139→      }
140→
141→      // Helper to update stream messages and optionally React state
142→      const updateMessages = (updater: (msgs: ChatMessage[]) => ChatMessage[]) => {
143→        state.messages = updater(state.messages);
144→        if (activeConversationIdRef.current === convId) {
145→          setMessages(state.messages);
146→        }
147→      };
148→
149→      // Helper to schedule text flush
150→      const scheduleFlush = () => {
151→        if (!state.flushTimer) {
152→          state.flushTimer = setTimeout(() => {
153→            flushTextForStream(state, convId!);
154→            state.flushTimer = null;
155→          }, 50);
156→        }
157→      };
158→
159→      // Helper to flush pending text immediately
160→      const flushNow = () => {
161→        if (state.flushTimer) {
162→          clearTimeout(state.flushTimer);
163→          state.flushTimer = null;
164→        }
165→        flushTextForStream(state, convId!);
166→      };
167→
168→      // Helper to finalize stream (called by onDone and onError)
169→      const cleanupStream = () => {
170→        if (state.flushTimer) {
171→          clearTimeout(state.flushTimer);
172→          state.flushTimer = null;
173→        }
174→        if (convId) {
175→          streamStatesRef.current.delete(convId);
176→          setStreamingConversationIds(prev => {
177→            const next = new Set(prev);
178→            next.delete(convId);
179→            return next;
180→          });
181→        }
182→      };
