184→      await runAgentLoop(
185→        actualMessage,
186→        state.sessionId,
187→        langfuseSessionId,
188→        pendingHistory ?? (history.length > 0 ? history : null),
189→        conversationId,
190→        {
191→          onTextChunk: (chunk) => {
192→            state.textBuffer += chunk;
193→            scheduleFlush();
194→          },
195→          onThinkingDone: () => {
196→            flushNow();
197→            if (state.currentText.trim()) {
198→              state.segments.push({ type: 'thinking', text: state.currentText });
199→              state.currentText = '';
200→            }
201→            state.phase = 'answer';
202→            updateMessages(msgs =>
203→              msgs.map(m =>
204→                m.id === assistantId
205→                  ? { ...m, currentPhase: 'answer', segments: [...state.segments] }
206→                  : m
207→              )
