705→  const respondToQuestion = useCallback(
706→    async (questionId: string, answers: string[], freeText?: string) => {
707→      // Find the stream state that contains this question
708→      let targetState: StreamState | undefined;
709→      let targetConvId: string | null = null;
710→
711→      // Search all active streams for the question
712→      for (const [cid, state] of streamStatesRef.current) {
713→        if (state.segments.some(s => s.type === 'user_question' && s.questionData?.questionId === questionId)) {
714→          targetState = state;
715→          targetConvId = cid;
716→          break;
717→        }
718→      }
719→
720→      if (targetState) {
721→        const segIdx = targetState.segments.findIndex(
722→          s => s.type === 'user_question' && s.questionData?.questionId === questionId
723→        );
724→        if (segIdx !== -1) {
725→          targetState.segments[segIdx] = {
