762→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
763→    const outgoing = outgoingConversationId || null;
764→    const incoming = incomingConversationId || null;
765→    activeConversationIdRef.current = incoming;
766→
767→    // Save outgoing conversation's messages to cache (only if not streaming --
768→    // streaming conversations keep their state in streamStatesRef)
769→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
770→      const currentMsgs = messagesRef.current;
771→      if (currentMsgs.length > 0) {
772→        messagesCacheRef.current.set(outgoing, currentMsgs);
773→      }
774→    }
775→
776→    // Check if incoming conversation has an active stream (re-attachment)
777→    if (incoming) {
778→      const streamState = streamStatesRef.current.get(incoming);
779→      if (streamState) {
780→        // Re-attach: use live stream messages
781→        setMessages(streamState.messages);
782→        setIsStreaming(true);
783→        return;
784→      }
785→    }
786→
787→    // No active stream -- use backend data or cache
788→    let finalMsgs = msgs;
789→    if (incoming) {
790→      const cached = messagesCacheRef.current.get(incoming);
791→      if (cached && cached.length > 0 && cached.length > msgs.length) {
792→        finalMsgs = cached;
793→      }
794→      messagesCacheRef.current.delete(incoming);
795→    }
796→
797→    setMessages(finalMsgs);
798→    const hasStreamingMsg = finalMsgs.some(m => m.isStreaming);
799→    setIsStreaming(hasStreamingMsg);
800→    sessionIdRef.current = null;
801→    pendingHistoryRef.current = null;
802→  }, []);
803→
804→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
805→    const outgoing = outgoingConversationId || null;
806→    activeConversationIdRef.current = null;
807→
808→    // Save outgoing messages to cache if not streaming
809→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
810→      const currentMsgs = messagesRef.current;
811→      if (currentMsgs.length > 0) {
812→        messagesCacheRef.current.set(outgoing, currentMsgs);
813→      }
814→    }
815→
816→    setMessages([]);
817→    setIsStreaming(false);
818→    sessionIdRef.current = null;
819→    pendingHistoryRef.current = null;
820→  }, []);
821→
822→  return (
823→    <AgentContext.Provider
824→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion, streamingConversationIds }}
825→    >
826→      {children}
827→    </AgentContext.Provider>
828→  );
829→}
