 86→        id: assistantId,
 87→        role: 'assistant',
 88→        content: '',
 89→        toolCalls: [],
 90→        isStreaming: true,
 91→      };
 92→
 93→      // Build conversation history from current messages or cached messages
 94→      const currentMsgs = convId && activeConversationIdRef.current === convId
