119→      }
120→
121→      // If this is the active conversation, update React state
122→      if (activeConversationIdRef.current === convId) {
123→        setMessages(streamMessages);
124→        setIsStreaming(true);
125→      }
126→
127→      // If there's pending history from a delete, start a new Langfuse session
128→      const pendingHistory = pendingHistoryRef.current;
129→      pendingHistoryRef.current = null;
130→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
131→
132→      // Extract skill references
