151→        if (!state.flushTimer) {
152→          state.flushTimer = setTimeout(() => {
153→            flushTextForStream(state, convId!);
154→            state.flushTimer = null;
155→          }, 50);
156→        }
157→      };
158→
159→      // Helper to flush pending text immediately
