354→            state.segments.push({ type: 'user_question', questionData: data });
355→            updateMessages(msgs =>
356→              msgs.map(m =>
357→                m.id === assistantId
358→                  ? { ...m, segments: [...state.segments] }
359→                  : m
360→              )
361→            );
362→          },
363→        },
364→        controller.signal,
365→        userSessionId,
366→        skills,
367→      );
368→    },
369→    [flushTextForStream, refreshTables, userSessionId]
370→  );
371→
372→  const editMessage = useCallback(
373→    async (messageIndex: number, newContent: string) => {
374→      const convId = activeConversationIdRef.current;
375→
376→      // If this conversation has an active stream, abort it first
377→      let existingMessages: ChatMessage[] | null = null;
378→      if (convId && streamStatesRef.current.has(convId)) {
379→        const existingState = streamStatesRef.current.get(convId)!;
380→        existingMessages = existingState.messages;
381→        existingState.abortController.abort();
382→        if (existingState.flushTimer) {
383→          clearTimeout(existingState.flushTimer);
384→        }
385→        streamStatesRef.current.delete(convId);
386→        setStreamingConversationIds(prev => {
387→          const next = new Set(prev);
388→          if (convId) next.delete(convId);
389→          return next;
390→        });
391→      }
392→
393→      // Truncate messages at the edit point in the backend
394→      if (convId) {
395→        try {
396→          await fetch(`/api/conversations/${convId}/messages?from_sort_order=${messageIndex}`, {
397→            method: 'DELETE',
398→          });
399→        } catch {
400→          // Best-effort
401→        }
402→        messagesCacheRef.current.delete(convId);
403→      }
404→
405→      // Build conversation history from messages before the edit point
406→      const currentMsgs = existingMessages || messagesRef.current;
407→      const conversationHistory: { role: string; content: string }[] = [];
408→      for (let i = 0; i < messageIndex; i++) {
409→        const msg = currentMsgs[i];
410→        if (msg.role === 'user' || msg.role === 'assistant') {
411→          conversationHistory.push({ role: msg.role, content: msg.content });
412→        }
413→      }
414→
415→      const controller = new AbortController();
416→      const assistantId = generateId();
417→
418→      const userMsg: ChatMessage = {
419→        id: generateId(),
420→        role: 'user',
421→        content: newContent,
422→      };
423→      const assistantMsg: ChatMessage = {
424→        id: assistantId,
425→        role: 'assistant',
426→        content: '',
427→        toolCalls: [],
428→        isStreaming: true,
429→      };
430→
431→      const truncatedMessages = currentMsgs.slice(0, messageIndex);
432→      const streamMessages = [...truncatedMessages, userMsg, assistantMsg];
433→
434→      // Create per-conversation stream state
435→      const state: StreamState = {
436→        assistantId,
437→        segments: [],
438→        currentText: '',
439→        textBuffer: '',
440→        phase: 'thinking',
441→        abortController: controller,
442→        sessionId: null, // Edit starts a fresh session
443→        messages: streamMessages,
444→        flushTimer: null,
445→      };
446→
447→      if (convId) {
448→        streamStatesRef.current.set(convId, state);
449→        setStreamingConversationIds(prev => new Set(prev).add(convId));
450→      }
451→
452→      setMessages(streamMessages);
453→      setIsStreaming(true);
454→
455→      // Helper to update stream messages and optionally React state
456→      const updateMessages = (updater: (msgs: ChatMessage[]) => ChatMessage[]) => {
457→        state.messages = updater(state.messages);
458→        if (activeConversationIdRef.current === convId) {
459→          setMessages(state.messages);
460→        }
461→      };
462→
463→      // Helper to schedule text flush
464→      const scheduleFlush = () => {
465→        if (!state.flushTimer) {
466→          state.flushTimer = setTimeout(() => {
467→            flushTextForStream(state, convId);
468→            state.flushTimer = null;
469→          }, 50);
470→        }
471→      };
472→
473→      // Helper to flush pending text immediately
474→      const flushNow = () => {
475→        if (state.flushTimer) {
476→          clearTimeout(state.flushTimer);
477→          state.flushTimer = null;
478→        }
479→        flushTextForStream(state, convId);
480→      };
481→
482→      // Helper to finalize stream
483→      const cleanupStream = () => {
484→        if (state.flushTimer) {
485→          clearTimeout(state.flushTimer);
486→          state.flushTimer = null;
487→        }
488→        if (convId) {
489→          streamStatesRef.current.delete(convId);
490→          setStreamingConversationIds(prev => {
491→            const next = new Set(prev);
492→            if (convId) next.delete(convId);
493→            return next;
494→          });
495→        }
496→      };
497→
498→      await runAgentEditLoop(
499→        newContent,
500→        conversationHistory,
501→        generateUUID(),
502→        {
503→          onTextChunk: (chunk) => {
504→            state.textBuffer += chunk;
505→            scheduleFlush();
506→          },
507→          onThinkingDone: () => {
508→            flushNow();
509→            if (state.currentText.trim()) {
510→              state.segments.push({ type: 'thinking', text: state.currentText });
511→              state.currentText = '';
512→            }
513→            state.phase = 'answer';
514→            updateMessages(msgs =>
515→              msgs.map(m =>
516→                m.id === assistantId
517→                  ? { ...m, currentPhase: 'answer', segments: [...state.segments] }
518→                  : m
519→              )
520→            );
521→          },
522→          onToolCall: (pending: ToolCallResult) => {
523→            flushNow();
524→            if (state.currentText.trim()) {
525→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
526→              state.segments.push({ type: segType, text: state.currentText });
527→              state.currentText = '';
528→            }
529→            state.segments.push({ type: 'tool', toolResult: pending });
530→            updateMessages(msgs =>
531→              msgs.map(m =>
532→                m.id === assistantId
533→                  ? { ...m, currentPhase: 'answer', segments: [...state.segments] }
534→                  : m
535→              )
536→            );
537→          },
538→          onToolResult: (result: ToolCallResult) => {
539→            const pendingIdx = state.segments.findIndex(
540→              s => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
541→            );
542→            if (pendingIdx !== -1) {
543→              const pending = state.segments[pendingIdx].toolResult!;
544→              state.segments[pendingIdx] = {
545→                type: 'tool',
546→                toolResult: {
547→                  ...pending,
548→                  ...result,
549→                  sql: result.sql || pending.sql,
550→                  toolName: result.toolName || pending.toolName,
551→                  command: result.command || pending.command,
552→                  toolInput: result.toolInput || pending.toolInput,
553→                },
554→              };
555→            } else {
556→              state.segments.push({ type: 'tool', toolResult: result });
557→            }
558→            updateMessages(msgs =>
559→              msgs.map(m =>
560→                m.id === assistantId
561→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...state.segments] }
562→                  : m
563→              )
564→            );
565→            refreshTables();
566→          },
567→          onSubagentStart: (data) => {
568→            flushNow();
569→            if (state.currentText.trim()) {
570→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
571→              state.segments.push({ type: segType, text: state.currentText });
572→              state.currentText = '';
573→            }
574→            state.segments.push({
575→              type: 'subagent_start',
576→              subagentId: data.id,
577→              subagentName: data.name,
578→              text: data.prompt,
579→            });
580→            updateMessages(msgs =>
581→              msgs.map(m =>
582→                m.id === assistantId
583→                  ? { ...m, segments: [...state.segments] }
584→                  : m
585→              )
586→            );
587→          },
588→          onSubagentEnd: (data) => {
589→            state.segments.push({
590→              type: 'subagent_end',
591→              subagentId: data.id,
592→              subagentName: data.name,
593→              chart_spec: data.chart_spec,
594→              sqlResults: data.sql_results,
595→              text: data.result,
596→            });
597→            updateMessages(msgs =>
598→              msgs.map(m =>
599→                m.id === assistantId
600→                  ? { ...m, segments: [...state.segments] }
601→                  : m
602→              )
603→            );
604→          },
605→          onDone: (newSessionId) => {
606→            if (newSessionId) {
607→              state.sessionId = newSessionId;
608→              sessionIdRef.current = newSessionId;
609→            }
610→            flushNow();
611→            if (state.currentText.trim()) {
612→              state.segments.push({ type: 'answer', text: state.currentText });
613→              state.currentText = '';
614→            }
615→            updateMessages(msgs =>
616→              msgs.map(m =>
617→                m.id === assistantId
618→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...state.segments] }
619→                  : m
620→              )
621→            );
622→            if (convId && activeConversationIdRef.current !== convId) {
623→              messagesCacheRef.current.set(convId, state.messages);
624→            }
625→            cleanupStream();
626→            if (activeConversationIdRef.current === convId) {
627→              setIsStreaming(false);
628→            }
629→          },
630→          onError: (error) => {
631→            flushNow();
632→            if (state.currentText.trim()) {
633→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
634→              state.segments.push({ type: segType, text: state.currentText });
635→              state.currentText = '';
636→            }
637→            state.segments.push({ type: 'error', errorMessage: error });
638→            updateMessages(msgs =>
639→              msgs.map(m =>
640→                m.id === assistantId
641→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...state.segments] }
642→                  : m
643→              )
644→            );
645→            if (convId && activeConversationIdRef.current !== convId) {
646→              messagesCacheRef.current.set(convId, state.messages);
647→            }
648→            cleanupStream();
649→            if (activeConversationIdRef.current === convId) {
650→              setIsStreaming(false);
651→            }
652→          },
653→          onUserQuestion: (data) => {
654→            flushNow();
655→            if (state.currentText.trim()) {
656→              const segType = state.phase === 'answer' ? 'answer' : 'thinking';
657→              state.segments.push({ type: segType, text: state.currentText });
658→              state.currentText = '';
659→            }
660→            state.segments.push({ type: 'user_question', questionData: data });
661→            updateMessages(msgs =>
662→              msgs.map(m =>
663→                m.id === assistantId
664→                  ? { ...m, segments: [...state.segments] }
665→                  : m
666→              )
667→            );
668→          },
669→        },
670→        controller.signal,
671→        userSessionId,
672→        convId,
673→      );
674→    },
675→    [flushTextForStream, refreshTables, userSessionId]
676→  );
677→
678→  const deleteMessage = useCallback(
679→    (messageIndex: number) => {
680→      const convId = activeConversationIdRef.current;
681→      // Only block if this specific conversation is streaming
682→      if (convId && streamStatesRef.current.has(convId)) return;
683→
684→      // Store remaining messages as history for Langfuse context on next send
685→      setMessages((prev) => {
686→        const remaining = prev.slice(0, messageIndex);
687→        pendingHistoryRef.current = remaining
688→          .filter((m) => m.role === 'user' || m.role === 'assistant')
689→          .map((m) => ({ role: m.role, content: m.content }));
690→        return remaining;
691→      });
692→
693→      // Persist the truncation to the backend
694→      if (convId) {
695→        fetch(`/api/conversations/${convId}/messages?from_sort_order=${messageIndex}`, {
696→          method: 'DELETE',
697→        }).catch(() => {
698→          // Best-effort: if this fails the UI is already updated
699→        });
700→        // Invalidate cache so switching back loads from backend
701→        messagesCacheRef.current.delete(convId);
702→      }
703→
704→      // Clear session so next message starts fresh
705→      sessionIdRef.current = null;
706→    },
707→    []
708→  );
709→
710→  const respondToQuestion = useCallback(
711→    async (questionId: string, answers: string[], freeText?: string) => {
712→      // Find the stream state that contains this question
713→      let targetState: StreamState | undefined;
714→      let targetConvId: string | null = null;
715→
716→      // Search all active streams for the question
717→      for (const [cid, state] of streamStatesRef.current) {
718→        if (state.segments.some(s => s.type === 'user_question' && s.questionData?.questionId === questionId)) {
719→          targetState = state;
720→          targetConvId = cid;
721→          break;
722→        }
723→      }
724→
725→      if (targetState) {
726→        const segIdx = targetState.segments.findIndex(
727→          s => s.type === 'user_question' && s.questionData?.questionId === questionId
728→        );
729→        if (segIdx !== -1) {
730→          targetState.segments[segIdx] = {
731→            ...targetState.segments[segIdx],
732→            userAnswer: answers,
733→            userFreeText: freeText,
734→          };
735→          targetState.messages = targetState.messages.map(m =>
736→            m.id === targetState!.assistantId
737→              ? { ...m, segments: [...targetState!.segments] }
738→              : m
739→          );
740→          if (activeConversationIdRef.current === targetConvId) {
741→            setMessages(targetState.messages);
742→          }
743→        }
744→      }
745→
746→      // POST to backend
747→      try {
748→        await fetch('/api/chat/respond', {
749→          method: 'POST',
750→          headers: {
751→            'Content-Type': 'application/json',
752→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
753→          },
754→          body: JSON.stringify({
755→            question_id: questionId,
756→            answers,
757→            free_text: freeText || null,
758→          }),
759→        });
760→      } catch (e) {
761→        console.error('Failed to respond to question:', e);
762→      }
763→    },
764→    [userSessionId]
765→  );
766→
767→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
768→    const outgoing = outgoingConversationId || null;
769→    const incoming = incomingConversationId || null;
770→    activeConversationIdRef.current = incoming;
771→
772→    // Save outgoing conversation's messages to cache (only if not streaming --
773→    // streaming conversations keep their state in streamStatesRef)
774→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
775→      const currentMsgs = messagesRef.current;
776→      if (currentMsgs.length > 0) {
777→        messagesCacheRef.current.set(outgoing, currentMsgs);
778→      }
779→    }
780→
781→    // Check if incoming conversation has an active stream (re-attachment)
782→    if (incoming) {
783→      const streamState = streamStatesRef.current.get(incoming);
784→      if (streamState) {
785→        // Re-attach: use live stream messages
786→        setMessages(streamState.messages);
787→        setIsStreaming(true);
788→        return;
789→      }
790→    }
791→
792→    // No active stream -- use backend data or cache
793→    let finalMsgs = msgs;
794→    if (incoming) {
795→      const cached = messagesCacheRef.current.get(incoming);
796→      if (cached && cached.length > 0 && cached.length > msgs.length) {
797→        finalMsgs = cached;
798→      }
799→      messagesCacheRef.current.delete(incoming);
800→    }
801→
802→    setMessages(finalMsgs);
803→    const hasStreamingMsg = finalMsgs.some(m => m.isStreaming);
804→    setIsStreaming(hasStreamingMsg);
805→    sessionIdRef.current = null;
806→    pendingHistoryRef.current = null;
807→  }, []);
808→
809→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
810→    const outgoing = outgoingConversationId || null;
811→    activeConversationIdRef.current = null;
812→
813→    // Save outgoing messages to cache if not streaming
814→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
815→      const currentMsgs = messagesRef.current;
816→      if (currentMsgs.length > 0) {
817→        messagesCacheRef.current.set(outgoing, currentMsgs);
818→      }
819→    }
820→
821→    setMessages([]);
822→    setIsStreaming(false);
823→    sessionIdRef.current = null;
824→    pendingHistoryRef.current = null;
825→  }, []);
826→
827→  return (
828→    <AgentContext.Provider
829→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion, streamingConversationIds }}
830→    >
831→      {children}
832→    </AgentContext.Provider>
833→  );
834→}
