710→  const respondToQuestion = useCallback(
711→    async (questionId: string, answers: string[], freeText?: string) => {
712→      // Find the stream state that contains this question
713→      let targetState: StreamState | undefined;
714→      let targetConvId: string | null = null;
715→
716→      // Search all active streams for the question
717→      for (const [cid, state] of streamStatesRef.current) {
718→        if (state.segments.some(s => s.type === 'user_question' && s.questionData?.questionId === questionId)) {
719→          targetState = state;
720→          targetConvId = cid;
721→          break;
722→        }
723→      }
724→
725→      if (targetState) {
726→        const segIdx = targetState.segments.findIndex(
727→          s => s.type === 'user_question' && s.questionData?.questionId === questionId
728→        );
729→        if (segIdx !== -1) {
730→          targetState.segments[segIdx] = {
731→            ...targetState.segments[segIdx],
732→            userAnswer: answers,
733→            userFreeText: freeText,
734→          };
735→          targetState.messages = targetState.messages.map(m =>
736→            m.id === targetState!.assistantId
737→              ? { ...m, segments: [...targetState!.segments] }
738→              : m
739→          );
740→          if (activeConversationIdRef.current === targetConvId) {
741→            setMessages(targetState.messages);
742→          }
743→        }
744→      }
745→
746→      // POST to backend
747→      try {
748→        await fetch('/api/chat/respond', {
749→          method: 'POST',
750→          headers: {
751→            'Content-Type': 'application/json',
752→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
753→          },
754→          body: JSON.stringify({
755→            question_id: questionId,
756→            answers,
757→            free_text: freeText || null,
758→          }),
759→        });
760→      } catch (e) {
761→        console.error('Failed to respond to question:', e);
762→      }
763→    },
764→    [userSessionId]
765→  );
766→
767→  const loadMessages = useCallback((msgs: ChatMessage[], outgoingConversationId?: string | null, incomingConversationId?: string | null) => {
768→    const outgoing = outgoingConversationId || null;
769→    const incoming = incomingConversationId || null;
770→    activeConversationIdRef.current = incoming;
771→
772→    // Save outgoing conversation's messages to cache (only if not streaming --
773→    // streaming conversations keep their state in streamStatesRef)
774→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
775→      const currentMsgs = messagesRef.current;
776→      if (currentMsgs.length > 0) {
777→        messagesCacheRef.current.set(outgoing, currentMsgs);
778→      }
779→    }
780→
781→    // Check if incoming conversation has an active stream (re-attachment)
782→    if (incoming) {
783→      const streamState = streamStatesRef.current.get(incoming);
784→      if (streamState) {
785→        // Re-attach: use live stream messages
786→        setMessages(streamState.messages);
787→        setIsStreaming(true);
788→        return;
789→      }
790→    }
791→
792→    // No active stream -- use backend data or cache
793→    let finalMsgs = msgs;
794→    if (incoming) {
795→      const cached = messagesCacheRef.current.get(incoming);
796→      if (cached && cached.length > 0 && cached.length > msgs.length) {
797→        finalMsgs = cached;
798→      }
799→      messagesCacheRef.current.delete(incoming);
800→    }
801→
802→    setMessages(finalMsgs);
803→    const hasStreamingMsg = finalMsgs.some(m => m.isStreaming);
804→    setIsStreaming(hasStreamingMsg);
805→    sessionIdRef.current = null;
806→    pendingHistoryRef.current = null;
807→  }, []);
808→
809→  const clearMessages = useCallback((outgoingConversationId?: string | null) => {
810→    const outgoing = outgoingConversationId || null;
811→    activeConversationIdRef.current = null;
812→
813→    // Save outgoing messages to cache if not streaming
814→    if (outgoing && !streamStatesRef.current.has(outgoing)) {
815→      const currentMsgs = messagesRef.current;
816→      if (currentMsgs.length > 0) {
817→        messagesCacheRef.current.set(outgoing, currentMsgs);
818→      }
819→    }
820→
821→    setMessages([]);
822→    setIsStreaming(false);
823→    sessionIdRef.current = null;
824→    pendingHistoryRef.current = null;
825→  }, []);
826→
827→  return (
828→    <AgentContext.Provider
829→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, loadMessages, respondToQuestion, streamingConversationIds }}
830→    >
831→      {children}
832→    </AgentContext.Provider>
833→  );
834→}
